/* @lc app=leetcode id=1865 lang=kotlin */ class FindSumPairs(val nums1: IntArray, val nums2: IntArray) { val count = HashMap<Int, Int>().apply { nums2.forEach { put(it, getOrDefault(it, 0) + 1) } } fun add(index: Int, v: Int) { nums2[index].let { old -> count[old] = count[old]!! - 1 }.run { nums2[index] += v }.run { count[nums2[index]] = count.getOrDefault(nums2[index], 0) + 1 } } fun count(tot: Int): Int = nums1.sumOf { count.getOrDefault(tot - it, 0) } }